scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 category2의 필터 라벨을 클릭한다. 	
    //1. Run the sample file and click on the filter label in category2.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_header_category2_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 필터항목(사용자필터,전체선택,kim,shin)이 보여진다.
    //1. Filter items (user filter, all selection, kim, shin) are shown.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_customFilter_scrollView').getStyle('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '전체선택'라벨을 2번 클릭한다.(선택박스나 오른쪽 여백부분아님)
    //2. Double-click the 'Select All' label (not the selection box or right margin)
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_text w2grid_customFilter_list_listColumn_text')[1].click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_text w2grid_customFilter_list_listColumn_text')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 전체해제후 다시 전체선택이 되어진다. (이전에는 전체해제후 다시 전체선택이 되어지지 않음)
    //2. After releasing the whole, the whole selection is made again. (Previously, the entire selection is not made again after the whole release)
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_customFilter_list_listColumn_checkbox')[1].checked", "true");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_customFilter_list_listColumn_checkbox')[2].checked", "true");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2list_listColumn w2list_listColumn_checkbox w2grid_customFilter_list_listColumn_checkbox')[3].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
